'use strict';

function makeColumnPlan(widths, gap) {
  if (!Array.isArray(widths)) throw new TypeError('widths must be an array');
  if (typeof gap !== 'number' || !Number.isFinite(gap)) throw new TypeError('gap must be finite');
  if (gap < 0) throw new RangeError('gap must be non-negative');

  for (const width of widths) {
    if (typeof width !== 'number' || !Number.isFinite(width)) {
      throw new TypeError('width must be finite');
    }
    if (width < 0) throw new RangeError('width must be non-negative');
  }

  const columns = [];
  let cursor = 0;
  for (let index = 0; index < widths.length; index += 1) {
    const width = widths[index];
    columns.push({ index, width, offset: cursor });
    cursor += width + gap;
  }

  return {
    columns,
    totalWidth: cursor
  };
}

module.exports = { makeColumnPlan };

