'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['makeColumnPlan']);
const { makeColumnPlan } = api;

assert.deepStrictEqual(makeColumnPlan([], 5), { columns: [], totalWidth: 0 });
assert.deepStrictEqual(makeColumnPlan([10], 7), {
  columns: [{ index: 0, width: 10, offset: 0 }],
  totalWidth: 10
});

const widths = [10.5, 0, 2.25];
const plan = makeColumnPlan(widths, 1.5);
assert.deepStrictEqual(plan, {
  columns: [
    { index: 0, width: 10.5, offset: 0 },
    { index: 1, width: 0, offset: 12 },
    { index: 2, width: 2.25, offset: 13.5 }
  ],
  totalWidth: 15.75
});
assert.deepStrictEqual(widths, [10.5, 0, 2.25]);
widths[0] = 99;
assert.strictEqual(plan.columns[0].width, 10.5);
const second = makeColumnPlan([10.5, 0, 2.25], 1.5);
assert.notStrictEqual(plan, second);
assert.notStrictEqual(plan.columns, second.columns);
assert.notStrictEqual(plan.columns[0], second.columns[0]);

for (const bad of [null, {}, '10']) {
  assert.throws(() => makeColumnPlan(bad, 1), TypeError);
}
for (const bad of [NaN, Infinity, '1', null]) {
  assert.throws(() => makeColumnPlan([], bad), TypeError);
}
for (const bad of [[1, '2'], [1, NaN], [Infinity], [undefined]]) {
  assert.throws(() => makeColumnPlan(bad, 1), TypeError);
}
assert.throws(() => makeColumnPlan([1, -0.5], 1), RangeError);
assert.throws(() => makeColumnPlan([1], -1), RangeError);

